# ==============================================================================
# Here we filter the hostname of a sending host.
# This is shown in the header under:
# "Received: from <hostname> (<hostname>) [ip address]"
#
# I only use this rarely or in emergencies.
#
# ------------------------------------------------------------------------------
# Language: -
# Weight:   1.0
# ==============================================================================

# A
# ------------------------------------------------------------------------------

# 16.08.26 - Phishing
# Sample: static195-133.de.dm.aliyun.com

/static\d{2,3}-\d{1,3}\.[a-z]{2}\.[a-z]{2}\.aliyun\.com/i 6.0

# B
# ------------------------------------------------------------------------------

# C
# ------------------------------------------------------------------------------
# 04.02.26 - Sample: cloud-hosting-1.shuangshixian.cn
/cloud-hosting-\d\.[a-z]{5,20}\.cn/i 6.0

# Sample: 107-172-135-68-host.colocrossing.com
/-host\.colocrossing\.com/i 6.0

